INSERT INTO "workflow_template" ("id", "name", "description", "category", "minPlan", "published", "nodes", "connections", "nodeTypes", "useCount", "createdById", "createdAt", "updatedAt")
VALUES ('tpl_shopify_order_paid_whatsapp', 'Shopify order paid: WhatsApp confirmation', 'When an order is paid in your Shopify store, the customer gets a confirmation on WhatsApp. Orders without a phone number are skipped. WhatsApp only lets a business start a conversation with an approved message template, so first create one in WhatsApp Manager named order_confirmation with four variables, for example: "Hi {{1}}, thank you for your order {{2}}. We received your payment of {{3}} {{4}}." To set it up: put your signing secret on the Shopify Trigger and create the Order payment webhook in Shopify with the trigger''s Webhook URL; on the WhatsApp node pick your credential and type your Phone Number ID. Only message customers who agreed to be contacted on WhatsApp. For WooCommerce, replace the trigger with a WooCommerce Trigger set to Order paid and use {{woocommerce.phone}}, {{woocommerce.customerName}}, {{woocommerce.order.number}}, {{woocommerce.order.total}} and {{woocommerce.order.currency}}.', 'E-commerce', 'FREE', true, '[{"id":"tpl_paid_trigger","type":"SHOPIFY_TRIGGER","position":{"x":0,"y":0},"data":{"event":"orders/paid"}},{"id":"tpl_paid_has_phone","type":"IF","position":{"x":320,"y":0},"data":{"combinator":"and","conditions":[{"inputKey":"shopify.phone","operator":"exists","value":""}]}},{"id":"tpl_paid_whatsapp","type":"WHATSAPP","position":{"x":640,"y":0},"data":{"variableName":"confirmation","operation":"send_template","phoneNumberId":"","to":"{{shopify.phone}}","templateName":"order_confirmation","languageCode":"en_US","templateParamsJson":"[{{json shopify.customerName}}, {{json shopify.order.name}}, {{json shopify.order.total_price}}, {{json shopify.order.currency}}]"}}]'::jsonb, '[{"fromNodeId":"tpl_paid_trigger","toNodeId":"tpl_paid_has_phone","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_paid_has_phone","toNodeId":"tpl_paid_whatsapp","fromOutput":"true","toInput":"target-1"}]'::jsonb, ARRAY['SHOPIFY_TRIGGER', 'IF', 'WHATSAPP']::text[], 0, 'system', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "workflow_template" ("id", "name", "description", "category", "minPlan", "published", "nodes", "connections", "nodeTypes", "useCount", "createdById", "createdAt", "updatedAt")
VALUES ('tpl_shopify_abandoned_cart_reminder', 'Shopify abandoned cart: email reminder', 'Every hour, looks for checkouts in your Shopify store that were started between one and two hours ago and never completed, and emails each shopper a link back to their cart. Because the schedule and the two time limits match, a checkout gets one reminder. To set it up: on the Shopify node pick your credential (its app needs the read_orders scope) and type your Shop Domain; on the Email node pick an SMTP credential and rewrite the message in your shop''s voice. If you change how often it runs, change the two time limits on the Shopify node to match. Shopify can send abandoned checkout emails by itself: switch that off in Shopify (Settings > Checkout) or shoppers get two. Only email shoppers where the law and your privacy policy allow it.', 'E-commerce', 'FREE', true, '[{"id":"tpl_cart_schedule","type":"SCHEDULE_TRIGGER","position":{"x":0,"y":0},"data":{"variableName":"scheduleTrigger","cronExpression":"0 * * * *"}},{"id":"tpl_cart_list","type":"SHOPIFY","position":{"x":320,"y":0},"data":{"variableName":"abandoned","operation":"list_abandoned_checkouts","shopDomain":"","minAgeMinutes":"60","maxAgeMinutes":"120","contactOnly":"true","limit":"50"}},{"id":"tpl_cart_split","type":"SPLIT_OUT","position":{"x":640,"y":0},"data":{"variableName":"checkouts","inputPath":"abandoned","field":"","include":"none"}},{"id":"tpl_cart_has_email","type":"IF","position":{"x":960,"y":0},"data":{"combinator":"and","conditions":[{"inputKey":"item.email","operator":"exists","value":""}]}},{"id":"tpl_cart_email","type":"EMAIL_SEND","position":{"x":1280,"y":0},"data":{"recipient":"{{item.email}}","subject":"You left something in your cart","body":"<p>Hi {{item.customer.first_name}},</p>\n<p>You started an order with us and did not finish it. Your cart is saved:</p>\n<p><a href=\"{{item.abandoned_checkout_url}}\">Return to your cart</a></p>\n<p>If you have a question about your order, reply to this email.</p>"}}]'::jsonb, '[{"fromNodeId":"tpl_cart_schedule","toNodeId":"tpl_cart_list","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_cart_list","toNodeId":"tpl_cart_split","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_cart_split","toNodeId":"tpl_cart_has_email","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_cart_has_email","toNodeId":"tpl_cart_email","fromOutput":"true","toInput":"target-1"}]'::jsonb, ARRAY['SCHEDULE_TRIGGER', 'SHOPIFY', 'SPLIT_OUT', 'IF', 'EMAIL_SEND']::text[], 0, 'system', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;
